module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic in,
    output logic out
);

    typedef enum logic {
        A = 1'b0,
        B = 1'b1
    } state_t;

    state_t current_state, next_state;

    // State register
    always_ff @(posedge clk) begin
        if (reset) begin
            current_state <= B;
        end else begin
            current_state <= next_state;
        end
    end

    // Next state logic
    always_comb begin
        case (current_state)
            B: begin
                if (in) next_state = B;
                else    next_state = A;
            end
            A: begin
                if (in) next_state = A;
                else    next_state = B;
            end
            default: next_state = B;
        endcase
    end

    // Output logic (Moore: output depends only on state)
    assign out = (current_state == B);

endmodule

